import{_ as t,o as a,c as r,a4 as d}from"./chunks/framework.C83Ss68L.js";const g=JSON.parse('{"title":"Upgrade Guides","description":"Per-major migration guides for KatanaKit — what broke, what was deprecated, and the exact change to make in your code.","frontmatter":{"title":"Upgrade Guides","description":"Per-major migration guides for KatanaKit — what broke, what was deprecated, and the exact change to make in your code."},"headers":[],"relativePath":"guides/upgrade-to/index.md","filePath":"guides/upgrade-to/index.md","lastUpdated":1791564980000}'),o={name:"guides/upgrade-to/index.md"};function s(i,e,n,h,l,p){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="upgrade-guides" tabindex="-1">Upgrade Guides <a class="header-anchor" href="#upgrade-guides" aria-label="Permalink to &quot;Upgrade Guides&quot;">​</a></h1><p>KatanaKit follows semantic versioning, and every major ships its own migration guide. Each one answers the same three questions in the same order:</p><ol><li><strong>What broke</strong> — the changes that stop your code compiling or change its behaviour.</li><li><strong>What is deprecated</strong> — announced here before it breaks, so you can move ahead of the next major.</li><li><strong>What changed</strong> — additions and internal reworks that need no action.</li></ol><table tabindex="0"><thead><tr><th>From</th><th>To</th><th>Guide</th></tr></thead><tbody><tr><td>5.2.x (and 5.x)</td><td><strong>v6</strong> — current major</td><td><a href="./v6">Upgrade to v6</a></td></tr><tr><td>4.x</td><td>v5</td><td><a href="./v5">Upgrade to v5</a></td></tr><tr><td>3.x</td><td>v4</td><td><a href="./v4">Upgrade to v4</a></td></tr><tr><td>2.x</td><td>v3</td><td><a href="./v3">Upgrade to v3</a></td></tr><tr><td>1.x</td><td>v2</td><td><a href="./v2">Upgrade to v2</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Patch and minor releases never break</p><p>Within a major, upgrades are <code>npm install katanakit-js@^6</code>. Breaking changes only ever land in a <code>.0.0</code> release; the rest of the story lives in the <a href="/katanakit-js/changelog">changelog</a>.</p></div><h2 id="not-sure-where-you-are" tabindex="-1">Not sure where you are? <a class="header-anchor" href="#not-sure-where-you-are" aria-label="Permalink to &quot;Not sure where you are?&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> katanakit-js</span></span></code></pre></div><p>Then follow the guide for the next major after your version and keep going — the guides are written to be applied in order, and each one assumes the state left behind by the previous one.</p>',8)])])}const u=t(o,[["render",s]]);export{g as __pageData,u as default};
